design_text:
{
  "site_summary": "A full shade, moderately moist courtyard housing one large dog.",
  "layout_strategy": "Upright shrubs and perennials create a sturdy mid layer against the courtyard walls that can withstand dog rubbing, complemented by a low ground layer of delicate foliage and a pet-accessible low grazing herb patch.",
  "combination_logic": "The scheme pairs the broad, strappy leaves and vibrant seasonal blooms of Clivia with the fine, textured aromatic foliage of mint and parsley. Glossy evergreen leaves of Laurus nobilis provide a permanent architectural anchor, while cyclamen and seasonal bulbs add bursts of unexpected contrast, transitioning from structural greenery in winter to bright floral accents in spring.",
  "zones": [
    {
      "zone_name": "Mid-Level Structural Wall",
      "zone_role": "screening",
      "layer": "mid",
      "placement": "Against the back courtyard wall in full shade, knee to waist height, protected from direct afternoon sun.",
      "plants": [
        {
          "scientific_name": "Laurus nobilis",
          "common_name": "Bay Laurel",
          "why": "Provides a sturdy, woody evergreen shrub structure that can handle being brushed against by a large dog.",
          "role_in_combination": "Acts as the permanent architectural backbone of the mid-layer, offering dark green, glossy texture year-round."
        },
        {
          "scientific_name": "Clivia miniata",
          "common_name": "Kaffir Lily",
          "why": "Thrives in full shade and moderate moisture, adding height and form.",
          "role_in_combination": "Contributes bold, strappy foliage contrast and striking orange seasonal flower clusters that pop against the dark bay laurel."
        }
      ],
      "maintenance": [
        "Water moderately when the top two inches of soil feel dry",
        "Feed with a balanced liquid fertilizer monthly during the spring and summer growing season",
        "Prune bay laurel lightly in late spring to maintain desired shape",
        "Repot every 2 to 3 years in fresh, well-draining potting mix"
      ]
    },
    {
      "zone_name": "Ground Level Shade Bed",
      "zone_role": "groundcover",
      "layer": "ground",
      "placement": "Along the perimeter floor of the courtyard in full shade, receiving indirect ambient light.",
      "plants": [
        {
          "scientific_name": "Cyclamen spp.",
          "common_name": "Cyclamen",
          "why": "Adapts well to bright indirect light and damp, shaded ground environments.",
          "role_in_combination": "Brings heart-shaped patterned foliage and delicate upward-facing blooms that carpet the base of the taller structural plants."
        },
        {
          "scientific_name": "Narcissus spp.",
          "common_name": "Daffodil",
          "why": "Adds seasonal rhythm to the dark corner of the courtyard.",
          "role_in_combination": "Provides bright yellow early-spring vertical focal points that emerge through the lower foliage layer before dying back cleanly."
        }
      ],
      "maintenance": [
        "Water when the soil surface dries slightly, ensuring pots or beds do not become waterlogged",
        "Remove spent flower stems and yellowing leaves promptly to prevent fungal rot",
        "Apply a low-nitrogen bulb fertilizer in early spring",
        "Divide overcrowded tubers or bulbs every few years during their summer dormancy"
      ]
    },
    {
      "zone_name": "Pet Grazing and Herb Corner",
      "zone_role": "grazing",
      "layer": "ground",
      "placement": "In an easily accessible corner on the courtyard floor, receiving moderate filtered light.",
      "plants": [
        {
          "scientific_name": "Mentha sp.",
          "common_name": "Mint",
          "why": "Grows vigorously in moist, shaded conditions and provides sensory stimulation for pets.",
          "role_in_combination": "Contributes a soft, sprawling green mat with aromatic foliage that contrasts in texture against the rigid architectural plants."
        },
        {
          "scientific_name": "Petroselinum crispum",
          "common_name": "Parsley",
          "why": "Thrives in moderate moisture and partial to full shade, perfectly safe for canine nibbling.",
          "role_in_combination": "Adds finely divided, ruffled green leaves that introduce a light, delicate foliage texture at the base of the composition."
        }
      ],
      "maintenance": [
        "Keep the soil consistently moist as these herbs prefer higher moisture levels",
        "Harvest frequently by snipping stems to encourage bushier, fresh growth",
        "Feed lightly with an organic liquid fertilizer once a month in spring",
        "Divide the mint root runners annually to prevent them from overtaking the container or bed"
      ]
    }
  ],
  "care_instructions": [
    {
      "task": "Check soil moisture levels across all courtyard zones to ensure adequate hydration without waterlogging.",
      "frequency": "Twice a week in summer, weekly in spring and autumn",
      "season": "Summer and Spring"
    },
    {
      "task": "Apply balanced liquid fertilizer to support foliage and seasonal blooms.",
      "frequency": "Monthly",
      "season": "Spring and Summer"
    },
    {
      "task": "Clear away fallen leaves and dead plant debris from the ground layer to prevent fungal disease in the damp shade.",
      "frequency": "Bi-weekly",
      "season": "Autumn and Winter"
    }
  ],
  "care_cautions": [
    "Clivia miniata contains alkaloids that are toxic if ingested, so ensure the large dog does not chew on the mid-layer Clivia leaves.",
    "Mint in the grazing corner can become overly aggressive and crowd out the parsley if its root spread is not routinely restricted.",
    "Full shade combined with overzealous watering in the ground layer can cause root rot in cyclamen tubers."
  ],
  "pet_safety_note": "The design designates a specific low-level grazing zone containing safe herbs like mint and parsley for the dog to interact with, while keeping toxic shade perennials safely elevated or out of direct chewing reach."
}
